<?php
declare(strict_types=1);
require_once dirname(__DIR__).'/bootstrap/app.php';
$admin=pf_require_admin($pdo);$error='';$notice='';
if($_SERVER['REQUEST_METHOD']==='POST'){pf_verify_csrf();$id=filter_input(INPUT_POST,'user_id',FILTER_VALIDATE_INT);$action=(string)($_POST['action']??'');$note=trim((string)($_POST['note']??''));$map=['approve'=>'ACTIVE','suspend'=>'SUSPENDED','reject'=>'REJECTED'];
 if(!$id||!isset($map[$action]))$error='Invalid advertiser action.';else{$pdo->beginTransaction();try{
  $q=$pdo->prepare('SELECT status FROM pf_advertiser_profiles WHERE user_id=? FOR UPDATE');$q->execute([$id]);$before=$q->fetchColumn();if($before===false)throw new RuntimeException('Advertiser profile not found.');$after=$map[$action];
  $pdo->prepare('UPDATE pf_advertiser_profiles SET status=?,reviewed_by=?,reviewed_at=NOW(),review_note=? WHERE user_id=?')->execute([$after,(int)$admin['id'],$note?:null,$id]);$paused=0;
  if($after!=='ACTIVE'){$p=$pdo->prepare("UPDATE pf_campaigns SET status='PAUSED' WHERE advertiser_id=? AND campaign_type IN ('SITE_DISPLAY','BLOG_SPONSORED') AND status='ACTIVE'");$p->execute([$id]);$paused=$p->rowCount();$pdo->prepare("UPDATE pf_site_campaigns s JOIN pf_campaigns c ON c.id=s.campaign_id SET s.status='PAUSED' WHERE c.advertiser_id=? AND s.status='ACTIVE'")->execute([$id]);$pdo->prepare("UPDATE pf_blog_campaigns b JOIN pf_campaigns c ON c.id=b.campaign_id SET b.status='PAUSED',b.sync_status='PENDING' WHERE c.advertiser_id=? AND b.status='ACTIVE'")->execute([$id]);}
  $ip=(string)($_SERVER['REMOTE_ADDR']??'');$ipBin=filter_var($ip,FILTER_VALIDATE_IP)?inet_pton($ip):null;$pdo->prepare('INSERT INTO pf_audit_log(actor_user_id,action,subject_type,subject_id,before_json,after_json,ip_address) VALUES (?,?,?,?,?,?,?)')->execute([(int)$admin['id'],'ADMIN_ADVERTISER_'.$action,'ADVERTISER',$id,json_encode(['status'=>$before]),json_encode(['status'=>$after,'campaigns_paused'=>$paused,'note'=>$note]),$ipBin]);$pdo->commit();$notice='Advertiser profile updated to '.$after.'.';
  if($after!=='ACTIVE'){$ids=$pdo->prepare("SELECT c.id FROM pf_campaigns c JOIN pf_blog_campaigns b ON b.campaign_id=c.id WHERE c.advertiser_id=? AND c.campaign_type='BLOG_SPONSORED' AND b.status='PAUSED'");$ids->execute([$id]);foreach($ids->fetchAll(PDO::FETCH_COLUMN) as $cid){$sync=pf_sync_blog_campaign($pdo,(int)$cid,'upsert');if(!$sync['ok'])pf_sync_blog_campaign($pdo,(int)$cid,'revoke');$pdo->prepare('UPDATE pf_blog_campaigns SET sync_status=?,last_sync_error=? WHERE campaign_id=?')->execute([$sync['ok']?'SYNCED':'FAILED',$sync['ok']?null:$sync['error'],$cid]);}}
 }catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$error=$e instanceof RuntimeException?$e->getMessage():'Advertiser profile update failed.';}}}
$rows=$pdo->query('SELECT p.user_id,p.advertiser_name,p.contact_email,p.website,p.description,p.review_note,p.status,p.created_at,u.name FROM pf_advertiser_profiles p JOIN users u ON u.id=p.user_id ORDER BY FIELD(p.status,"PENDING","ACTIVE","SUSPENDED","REJECTED"),p.created_at DESC LIMIT 300')->fetchAll();
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Advertiser management | PoketFlow</title><link rel="stylesheet" href="../assets/marketplace.css"><style>.table-wrap{overflow:auto}table{width:100%;border-collapse:collapse;text-align:left}th,td{padding:12px;border-bottom:1px solid var(--line);white-space:nowrap}.inline{display:inline-flex;gap:6px;flex-wrap:wrap}</style></head><body><header class="topbar"><a class="brand" href="../index.php"><span class="brand-mark">P</span><span>Poket<span>Flow</span></span></a><nav><a href="index.php">Admin home</a><a href="campaigns.php">Campaigns</a><a href="placements.php">Placements</a><a href="finance.php">Finance</a><a href="users.php">Members</a></nav></header><main class="container"><section class="welcome"><p class="eyebrow">ADVERTISER CONTROL</p><h1>Advertiser profiles</h1><p class="muted">Approve, suspend or reject advertiser access without changing member logins, passwords, IDs or historical ledger records.</p></section><?php if($error):?><div class="alert"><?=pf_e($error)?></div><?php endif;?><?php if($notice):?><div class="panel"><?=pf_e($notice)?></div><?php endif;?><section class="panel"><div class="table-wrap"><table><thead><tr><th>Advertiser</th><th>Contact</th><th>Website</th><th>Status</th><th>Joined</th><th>Action</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><strong><?=pf_e($r['advertiser_name'])?></strong><br><span class="small muted">User #<?=(int)$r['user_id']?> · <?=pf_e($r['name'])?></span><br><span class="small muted"><?=pf_e((string)$r['description'])?></span></td><td><?=pf_e($r['contact_email'])?></td><td><?=pf_e((string)$r['website'])?></td><td><?=pf_e($r['status'])?></td><td><?=pf_e($r['created_at'])?></td><td><form class="inline" method="post"><input type="hidden" name="_token" value="<?=pf_e(pf_csrf_token())?>"><input type="hidden" name="user_id" value="<?=(int)$r['user_id']?>"><input name="note" placeholder="Admin note" maxlength="500"><?php if($r['status']!=='ACTIVE'):?><button class="button primary" name="action" value="approve">Approve</button><?php endif;?><?php if($r['status']!=='SUSPENDED'):?><button class="button" style="background:#fff1f2;color:#9f1239" name="action" value="suspend">Suspend</button><?php endif;?><?php if($r['status']!=='REJECTED'):?><button class="button" style="background:#fff1f2;color:#9f1239" name="action" value="reject">Reject</button><?php endif;?></form></td></tr><?php endforeach;?></tbody></table></div></section></main></body></html>
